    def __init__(self, name): self.name = name
    def describe(self): return 'Person: ' + self.name

exercises.solution:
def describe_any(x):
    if isinstance(x, int):
        print(f"int: {x}")
    elif isinstance(x, str):
        print(f"string: {x}")
    else:
        print("unknown")

describe_any(42)
describe_any("hello")

