class Dog:
    def speak(self): return 'Woaf'
class Cat:
    def speak(self): return 'Mew'

for s in [Dog(), Cat()]:
    print(s.speak())

items = [42, 'hello', 3.14]
for item in items:
    if isinstance(item, int):
        print(f'int: {item}')
    elif isinstance(item, str):
        print(f'string: {item}')
    elif isinstance(item, float):
        print(f'float64: {item}')
